/*
 * A045005  Numbers whose base-3 representation contains exactly three 0's and
 *          one 2.
 * https://oeis.org/A045005
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = number whose base‑3 representation contains exactly three
 *            0's and one 2. The sequence is generated by enumerating all
 *            base‑3 strings of length L (L ≥ 4) with one digit 2, three
 *            digits 0 (none of which may be the most significant digit), and
 *            all other digits 1. The values are produced in as...
 * Range:     u8 n <= 9, u16 n <= 46, u32 n <= 46, u64 n <= 46, u128 n <= 46,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

/* comparison routine for qsort */
static int cmp_seq(const void *p1, const void *p2)
{
    const seq_t *x = (const seq_t *)p1;
    const seq_t *y = (const seq_t *)p2;
    if (*x < *y) return -1;
    if (*x > *y) return 1;
    return 0;
}

seq_t a(idx_t n)
{
    /* static state for memoisation */
    static bool init = false;
    static seq_t *nums = NULL;    /* stored terms */
    static size_t num_cap = 0;
    static idx_t num_len = 0;
    static idx_t cur_len = 0;     /* length processed up to */

    static seq_t *pow3 = NULL;    /* pow3[i] = 3^i */
    static size_t pow3_cap = 0;   /* current capacity of pow3 */

    if (!init) {
        init = true;
        nums = NULL;
        num_cap = 0;
        num_len = 0;
        cur_len = 0;
        pow3 = NULL;
        pow3_cap = 0;
    }

    /* generate terms until we have at least n of them */
    while (num_len < n) {
        /* next length to process */
        idx_t L = cur_len + 1;

        /* lengths below 4 cannot contain the pattern */
        if (L < 4) {
            cur_len = L;
            continue;
        }

        /* number of ways to choose 3 zero positions from 0..L-2 */
        idx_t zero_combos = 0;
        if (L - 1 >= 3) {
            zero_combos = ((L - 1) * (L - 2) * (L - 3)) / 6;   /* C(L-1,3) */
        }
        idx_t countL = zero_combos * (L - 3);                 /* total numbers of length L */

        /* ensure pow3 array covers required exponents */
        if ((size_t)L > pow3_cap) {
            size_t new_cap = (size_t)L;
            seq_t *new_pow3 = (seq_t *)realloc(pow3, new_cap * sizeof(seq_t));
            if (!new_pow3) return 0;           /* allocation failure (unlikely) */
            size_t start = pow3_cap;
            if (start == 0) {
                new_pow3[0] = (seq_t)1;
                start = 1;
            }
            for (size_t i = start; i < new_cap; ++i) {
                new_pow3[i] = new_pow3[i - 1] * (seq_t)3;
            }
            pow3 = new_pow3;
            pow3_cap = new_cap;
        }

        /* temporary array for numbers of current length */
        seq_t *tmp = (seq_t *)malloc((size_t)countL * sizeof(seq_t));
        if (!tmp) return 0;           /* allocation failure (unlikely) */

        /* base value with all digits equal to 1 */
        seq_t base_all = (seq_t)0;
        for (idx_t i = 0; i < L; ++i) {
            base_all += pow3[i];
        }

        /* generate all valid numbers for this length */
        size_t k = 0;   /* index in tmp */
        for (idx_t a = 0; a <= L - 4; ++a) {
            for (idx_t b = a + 1; b <= L - 3; ++b) {
                for (idx_t c = b + 1; c <= L - 2; ++c) {
                    for (idx_t p2 = 0; p2 < L; ++p2) {
                        if (p2 == a || p2 == b || p2 == c) continue;
                        tmp[k++] = base_all
                                   - pow3[a] - pow3[b] - pow3[c]
                                   + pow3[p2];
                    }
                }
            }
        }

        /* sort the numbers of this length */
        qsort(tmp, (size_t)countL, sizeof(seq_t), cmp_seq);

        /* append sorted numbers to global array */
        if (num_len + countL > num_cap) {
            size_t new_cap = num_len + countL + 1024;
            seq_t *new_nums = (seq_t *)realloc(nums, new_cap * sizeof(seq_t));
            if (!new_nums) {
                free(tmp);
                return 0;               /* allocation failure (unlikely) */
            }
            nums = new_nums;
            num_cap = new_cap;
        }
        memcpy(nums + num_len, tmp, (size_t)countL * sizeof(seq_t));
        num_len += countL;
        free(tmp);

        cur_len = L;
    }

    /* return the n‑th term (1‑based) */
    return nums[n - 1];
}
